// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {W_WALLET, Log} from "../src/W_WALLET.sol";

contract InvMutTest is Test {
    W_WALLET c;
    function setUp() public { c = new W_WALLET(address(new Log())); }

    function testFuzz_property(uint256 ts, uint256 t, address actor, uint256 amount) public {
        vm.assume(actor != address(0));
        uint256 t0 = bound(ts, 1, 365 days);
        uint256 amt = bound(amount, 0, 100 ether);
        uint256 tU = bound(t, 0, 365 days);
        vm.warp(t0);
        vm.deal(actor, amt);
        vm.prank(actor);
        c.Put{value: amt}(tU);
        (uint256 unlockTime,) = c.Acc(actor);
        assertTrue(unlockTime >= t0 && unlockTime >= tU && unlockTime != 0);
    }
}
